576			pm := donePM(t, f, webSource)
577			rows := rowKinds(pm)
578	
579			pm = openedPicker(t, pm) // the cursor starts on web-1, the entry in use
580			pm, _ = pmFeed(t, pm, testutil.Key("enter"))
581	
582			if pm.state != pathDone || !slices.Equal(rowKinds(pm), rows) {
583				t.Errorf("state %v rows %v, want done with the rows %v kept", pm.state, rowKinds(pm), rows)
584			}
585		})
586	}
587	
588	// Trace again and the Diagnostics hand-off reset what the column showed.
589	func TestPathRelaunchAndPrefillResetTheContainer(t *testing.T) {
590		f := runningFake()
591		f.inspectNet = appNetworking()
592	
593		pm := donePM(t, f, webSource)
594		if pm.container == nil {
595			t.Fatal("precondition: a done run from a container holds its container")
596		}
597		pm, _ = pmFeed(t, pm, testutil.Key("enter"))
598		if pm.container != nil || len(pm.table.Items()) != 0 {
599			t.Errorf("trace again kept container %v and %d rows", pm.container, len(pm.table.Items()))
600		}
601	
602		pm = donePM(t, f, webSource)
603		pm.prefill("example.org")
604		if !pm.source.isHost() || pm.container != nil {
605			t.Errorf("prefill left source %+v, container %v, want this machine and none", pm.source, pm.container)
606		}
607	}
608	
609	// Criterion 7 of the view: the composed body is exactly as wide as the table,
610	// at 80 and 60 columns, with no escape sequence cut.
611	func TestPathSelectorComposesAtTheTableWidth(t *testing.T) {
612		var rows []docker.Container
613		for i := range 40 {
614			rows = append(rows, docker.Container{
615				ID: fmt.Sprintf("%012x", i+1), Name: fmt.Sprintf("container-%02d-%s", i, strings.Repeat("x", 60)),
616				Image: "registry.example.com/team/image", State: "running",
617			})
618		}
619		for _, width := range []int{80, 60} {
620			t.Run(fmt.Sprint(width), func(t *testing.T) {
621				f := &fakeEngine{psRows: rows}
622				pm := newPathModel(f.engine())
623				pm.resize(width, 24)
624				route := pathRoute{Known: true, Interface: "eth0", Source: netip.MustParseAddr("192.168.1.2"), Gateway: netip.MustParseAddr("192.168.1.1")}
625				pm.route = &route
626				for ttl := 1; ttl <= 10; ttl++ {
627					pm.hops = append(pm.hops, hopAt(ttl))
628				}
629				pm.refreshSteps()
630				base := strings.Split(pm.view(), "\n")
631	
632				pm = openedPicker(t, pm)
633				got := strings.Split(pm.view(), "\n")
634	
635				if len(got) != len(base) {
636					t.Fatalf("%d lines with the selector, %d without", len(got), len(base))
637				}
638				for i, line := range got {
639					if w, want := ansi.StringWidth(line), ansi.StringWidth(base[i]); w != want {
640						t.Errorf("line %d is %d cells wide, want %d: %q", i, w, want, ansi.Strip(line))
641					}
642					if plain := ansi.Strip(line); strings.ContainsRune(plain, '\x1b') || strings.Contains(plain, "38;2;") {
643						t.Errorf("line %d holds a cut escape sequence: %q", i, plain)
644					}
645				}
646				if !strings.Contains(ansi.Strip(strings.Join(got, "\n")), "Trace from") {
647					t.Error("the selector is not drawn")
648				}
649			})
650		}
651	}
652	
653	// Rule 130: the key is advertised in editing and done, greyed where the trace
654	// is unsupported; the open selector replaces the list (a mode).
655	func TestPathSourceShortcuts(t *testing.T) {
656		pm := pmWith(t, runningFake())
657		for _, state := range []pathState{pathEditing, pathDone} {
658			pm.state = state
659			sc := pm.shortcuts()
660			if !testutil.ShortcutEnabled(sc, "ctrl+o") {
661				t.Errorf("state %v: ctrl+o is not advertised and enabled", state)
662			}
663			for _, s := range sc {
664				if s.Key == "ctrl+o" && s.Description != "Trace from…" {
665					t.Errorf("state %v: ctrl+o description = %q, want %q", state, s.Description, "Trace from…")
666				}
667			}
668		}
669	
670		off := pmWith(t, &fakeEngine{})
671		off.engine.supported = func() error { return errors.New("not linux") }
672		if sc := off.shortcuts(); !testutil.HasShortcut(sc, "ctrl+o") || !testutil.ShortcutDisabled(sc, "ctrl+o") {
673			t.Error("ctrl+o must stay listed and greyed where the trace is unsupported")
674		}
675	
676		pm.state = pathEditing
677		pm = openedPicker(t, pm)
678		if got, want := testutil.ShortcutKeys(pm.shortcuts()), []string{"↑↓", "enter", "esc"}; !slices.Equal(got, want) {
679			t.Errorf("selector shortcuts = %v, want %v", got, want)
680		}
681	}
682	
683	// Rule 114: the help names the key.
684	func TestPathSourceKeyIsInTheHelp(t *testing.T) {
685		c := New(testConfig()).GetHelpContent()
686		found := false
687		for _, kb := range c.KeyBindings {
688			if strings.HasPrefix(kb.Key, "ctrl+o") {
689				found = true
690			}
691		}
692		if !found {
693			t.Error("no KeyBinding starts with ctrl+o")
694		}
695		for _, s := range c.Sections {
696			if strings.HasPrefix(s.Title, "Path Tab") && strings.Contains(s.Body, "ctrl+o") {
697				return
698			}
699		}
700		t.Error("the Path Tab help section does not mention ctrl+o")
701	}
702

