26	// pathEngine is the seam between the path tab and the network: tests replace
27	// it with a fake.
28	type pathEngine struct {
29		supported func() error
30		resolve   func(ctx context.Context, host string) ([]netip.Addr, error)
31		route     func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error)
32		trace     func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
