29	var webSource = pathSource{ID: idWeb, Name: "web-1", Image: "nginx"}
30	
31	// runningFake offers api and web-1 (running) and db (paused).
32	func runningFake() *fakeEngine {
33		return &fakeEngine{psRows: []docker.Container{
34			{ID: idWeb, Name: "web-1", Image: "nginx", State: "running"},
35			{ID: idAPI, Name: "api", Image: "app", State: "running"},
36			{ID: idDB, Name: "db", Image: "postgres", State: "paused"},
37		}}
