41	func appNetworking() docker.ContainerNetworking {
42		return docker.ContainerNetworking{
43			Name: "web-1", Running: true, Mode: "app_net",
44			Networks: []docker.EndpointNetwork{{
45				Name:    "app_net",
46				IPv4:    netip.MustParseAddr("172.18.0.5"),
47				Gateway: netip.MustParseAddr("172.18.0.1"),
48			}},
49		}
50	}
51	
52	func pmWith(t *testing.T, f *fakeEngine) *PathModel {
53		t.Helper()
54		pm := newPathModel(f.engine())
55		pm.resize(120, 30)
56		return pm
57	}
58	
59	// pressedSourceKey presses ctrl+o and returns the model, the Cmd and the
60	// message the Cmd answers with.
61	func pressedSourceKey(t *testing.T, pm *PathModel) (*PathModel, tea.Msg) {
62		t.Helper()
63		pm, cmd := pmFeed(t, pm, testutil.Key("ctrl+o"))
64		return pm, testutil.Msg(cmd)
65	}
66	
67	// openedPicker presses ctrl+o and delivers the answer of the listing.
68	func openedPicker(t *testing.T, pm *PathModel) *PathModel {
69		t.Helper()
70		pm, msg := pressedSourceKey(t, pm)
71		if _, ok := msg.(pathSourcesMsg); !ok {
72			t.Fatalf("ctrl+o produced %T, want a pathSourcesMsg from the listing Cmd", msg)
73		}
74		pm, _ = pmFeed(t, pm, msg)
75		return pm
76	}
77	
78	// chosen opens the selector, moves down n entries (0 is this machine) and
79	// presses enter.
80	func chosen(t *testing.T, pm *PathModel, n int) *PathModel {
81		t.Helper()
82		pm = openedPicker(t, pm)
83		for range n {
84			pm, _ = pmFeed(t, pm, testutil.Key("down"))
85		}
86		pm, _ = pmFeed(t, pm, testutil.Key("enter"))
87		return pm
