91		var out []string
92		for _, s := range pm.table.Items() {
93			out = append(out, s.stepCell())
94		}
95		return out
96	}
97	
98	func rowAddress(pm *PathModel, i int) string {
99		items := pm.table.Items()
100		if i >= len(items) {
101			return "<no row>"
102		}
103		return items[i].addressCell()
104	}
105	
106	// donePM returns a model whose trace of 1.1.1.1 from src is done, with one hop.
107	func donePM(t *testing.T, f *fakeEngine, src pathSource) *PathModel {
108		t.Helper()
109		pm := pmWith(t, f)
110		if !src.isHost() {
111			pm.source = src
112		}
113		pm, _ = launched(t, pm, "1.1.1.1")
114		gen := pm.gen
115		pm, _ = pmFeed(t, pm,
116			pathResolvedMsg{gen: gen, addr: netip.MustParseAddr("1.1.1.1"), route: defaultRouteHop(), source: src, ctr: f.inspectNet},
117			pathHopMsg{gen: gen, hop: hopAt(1)},
118			pathDoneMsg{gen: gen, result: nettrace.Result{Outcome: nettrace.OutcomeReached, Hops: []nettrace.Hop{hopAt(1)}}},
119		)
120		if pm.state != pathDone {
121			t.Fatalf("precondition: state = %v, want pathDone", pm.state)
122		}
123		return pm
124	}
125	
126	// Criterion 1 and the key: ctrl+o opens the selector from editing and from
127	// done, reads the engine in the Cmd only, and shows the loading state in the
128	// footer while the body stays the table (Rules 110, 128, 139).
129	func TestPathSourceKeyOpensTheSelector(t *testing.T) {
130		for _, state := range []string{"editing", "done"} {
131			t.Run(state, func(t *testing.T) {
132				f := runningFake()
133				pm := pmWith(t, f)
134				if state == "done" {
135					pm.state = pathDone
136					pm.input.Blur()
137				}
138				baseLines := len(strings.Split(pm.view(), "\n"))
139				before := pm.sourcesGen
140	
141				pm, msg := pressedSourceKey(t, pm)
142	
143				if !pm.pickerOpen() {
144					t.Fatal("ctrl+o did not open the selector")
145				}
146				if pm.sourcesGen <= before {
147					t.Errorf("sourcesGen = %d, want a fresh value above %d", pm.sourcesGen, before)
148				}
149				got, ok := msg.(pathSourcesMsg)
150				if !ok || got.gen != pm.sourcesGen {
151					t.Fatalf("the Cmd answered %#v, want a pathSourcesMsg of gen %d", msg, pm.sourcesGen)
152				}
153				if st := pm.statusLine(); !st.Activity || st.Text != loadingText {
154					t.Errorf("statusLine while loading = %+v, want the shared activity dot with %q", st, loadingText)
155				}
156				body := ansi.Strip(pm.view())
157				if !strings.Contains(body, "Trace from") || !strings.Contains(body, "this machine") {
158					t.Errorf("the selector is not drawn over the table:\n%s", body)
159				}
160				if n := len(strings.Split(pm.view(), "\n")); n != baseLines {
161					t.Errorf("the view has %d lines with the selector, %d without: the body must stay the table", n, baseLines)
162				}
163			})
164		}
165	}
166	
167	// The engine is read by the Cmd, not by Update (Rule 110).
168	func TestPathSourceKeyReadsTheEngineInTheCmdOnly(t *testing.T) {
169		f := runningFake()
170		pm := pmWith(t, f)
171	
172		pm, cmd := pmFeed(t, pm, testutil.Key("ctrl+o"))
173	
174		if !pm.pickerOpen() || cmd == nil {
175			t.Fatalf("pickerOpen = %v, cmd nil = %v, want an open selector and a listing Cmd", pm.pickerOpen(), cmd == nil)
176		}
177		if f.osCalls+f.psCalls != 0 {
178			t.Errorf("Update read the engine (info %d, ps %d); only the Cmd may", f.osCalls, f.psCalls)
179		}
180	}
181	
182	func TestPathSourceKeyReopenedGetsANewGeneration(t *testing.T) {
183		pm := pmWith(t, runningFake())
184		pm = openedPicker(t, pm)
185		first := pm.sourcesGen
186		pm, _ = pmFeed(t, pm, testutil.Key("esc"))
187	
188		pm = openedPicker(t, pm)
189	
190		if pm.sourcesGen <= first {
191			t.Errorf("sourcesGen = %d after the second opening, want above %d", pm.sourcesGen, first)
192		}
193	}
194	
