	switch pm.state {
	case pathEditing:
		return pm.handleEditKey(msg)
	case pathRunning:
		if key == "esc" {
			return pm.cancelRun()
		}
	case pathDone:
		switch key {
		case "enter":
			return pm.launch(pm.target)
